void measure_wakeup(int iters, long period_ns) {
  static std::array<uint64_t, 1000> hist{};  // 1us buckets, last = overflow
  int64_t max_ns = 0;
  timespec next;
  clock_gettime(CLOCK_MONOTONIC, &next);
  for (int i = 0; i < iters; ++i) {
    next.tv_nsec += period_ns;
    while (next.tv_nsec >= 1000000000L) { next.tv_nsec -= 1000000000L; ++next.tv_sec; }
    clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &next, nullptr);
    timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    int64_t lat = (now.tv_sec - next.tv_sec) * 1000000000LL + (now.tv_nsec - next.tv_nsec);
    if (lat > max_ns) max_ns = lat;
    size_t b = std::min<size_t>(static_cast<size_t>(lat / 1000), hist.size() - 1);
    ++hist[b];
  }
  // Report hist and max_ns here, after the loop (I/O outside the timed part).
}
